const ri = (a, b) => a + Math.floor(rnd() * (b - a + 1));
const pick = (xs) => xs[ri(0, xs.length - 1)];
const KEYS = ['a', 'b', 'enabled', 'limits', 'layout', 'items', 'theme', 'x1', 'name'];
const scalar = () => pick([null, true, false, ri(-5, 99), '', 'red', 'x' + ri(0, 9)]);
const kind = (v) => v !== null && typeof v === 'object' ? (Array.isArray(v) ? 'arr' : 'obj') : 'scalar';
function genValue(d) { const k = ri(0, d > 0 ? 3 : 0);
  if (k === 0) return scalar();
  if (k === 1) return Array.from({ length: ri(0, 3) }, scalar);
  if (k === 2) return Array.from({ length: ri(0, 3) }, () => genObj(d - 1));
