function genPatch(base) { const p = {};
  for (const k of Object.keys(base)) { if (rnd() < 0.5) continue; const v = base[k];
    if (kind(v) === 'obj') p[k] = genPatch(v);
    else if (kind(v) === 'arr') { const isObj = v.length && kind(v[0]) === 'obj';
      p[k] = isObj ? v.slice(0, ri(0, v.length)).map(genPatch) : Array.from({ length: ri(0, 3) }, scalar); }
    else p[k] = scalar(); }
  const fresh = KEYS.filter((k) => !(k in base)); if (fresh.length && rnd() < 0.6) p[pick(fresh)] = genValue(1);
  return p; }
