function check(label, a, b) { n++; if (!same(a, b)) { bad++; if (bad < 5) console.log('MISMATCH', label, JSON.stringify(a), JSON.stringify(b)); } }
// given examples
const ex = [[{}, { enabled: 17 }], [{ limits: {}, enabled: '' }, { limits: { enabled: 63 }, enabled: '', layout: {} }]];
for (const [b, p] of ex) check('applyPatch example', oldM.applyPatch(clone(b), clone(p)), newM.applyPatch(clone(b), clone(p)));
for (const s of ['Width.91-ApiWidth.', 'Apiurl api_0-36']) check('toTitle example ' + s, oldM.toTitle(s), newM.toTitle(s));
const bl = ['red', [{ enabled: { theme: 'compact', enabled: 'blue' }, items: '' }, {}]];
for (const v of [...bl, null, true, 5, -5, 99, '', [], {}]) check('isBlank ' + JSON.stringify(v), oldM.isBlank(v), newM.isBlank(v));
// random in-range applyPatch
for (let i = 0; i < 50000; i++) { const b = genObj(3); const p = genPatch(b);
  check('applyPatch', oldM.applyPatch(clone(b), clone(p)), newM.applyPatch(clone(b), clone(p))); }
// toTitle random ASCII
const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 -_.';
for (let i = 0; i < 100000; i++) { let s = ''; for (let j = ri(0, 40); j > 0; j--) s += chars[ri(0, chars.length - 1)];
  check('toTitle ' + s, oldM.toTitle(s), newM.toTitle(s)); }
