  if (k === 0) return pick([null, true, false, ri(-5, 99), 'x', '']);
  if (k === 1) return pick([null, true, false, ri(-5, 99), 'x', '']);
  if (k === 2) return Array.from({ length: ri(0, 3) }, () => jsonVal(d - 1));
  if (k === 3) { const o = {}; for (let i = ri(0, 3); i > 0; i--) o[pick(KEYS)] = jsonVal(d - 1); return o; }
  return Array.from({ length: ri(0, 3) }, () => jsonVal(d - 1)); };
for (let i = 0; i < 100000; i++) { const v = jsonVal(2); check('isBlank ' + JSON.stringify(v), oldM.isBlank(v), newM.isBlank(v)); }
console.log(`checked ${n}, mismatches ${bad}`);
EOF
